use super::*;
use std::sync::Mutex;

fn pcm_wav(samples:&[i32])->Vec<u8> {
    let size=samples.len() as u32*4;
    let mut bytes=b"RIFF".to_vec();bytes.extend((36+size).to_le_bytes());bytes.extend(b"WAVEfmt ");bytes.extend(16_u32.to_le_bytes());bytes.extend(1_u16.to_le_bytes());bytes.extend(2_u16.to_le_bytes());bytes.extend(48000_u32.to_le_bytes());bytes.extend((48000_u32*8).to_le_bytes());bytes.extend(8_u16.to_le_bytes());bytes.extend(32_u16.to_le_bytes());bytes.extend(b"data");bytes.extend(size.to_le_bytes());for sample in samples{bytes.extend(sample.to_le_bytes());}bytes
}
struct Environment(Option<std::ffi::OsString>);
impl Drop for Environment {fn drop(&mut self){if let Some(value)=&self.0{std::env::set_var("ALSA_CONFIG_PATH",value);}else{std::env::remove_var("ALSA_CONFIG_PATH");}}}

#[tokio::test(flavor="multi_thread",worker_threads=4)]
async fn actual_bridge_downloads_only_selected_rates_and_continuous_alsa_matches_direct_fir_with_full_tail() {
    let root=tempfile::tempdir().unwrap();let capture=root.path().join("captured.pcm");let missing=root.path().join("missing.pcm");let config=root.path().join("alsa.conf");
    std::fs::write(&config,format!("pcm.null {{ type null }}\npcm.capture {{ type file slave.pcm null file \"{}\" format raw }}\npcm.missing {{ type file slave.pcm null file \"{}\" format raw }}\n",capture.display(),missing.display())).unwrap();let _environment=Environment(std::env::var_os("ALSA_CONFIG_PATH"));std::env::set_var("ALSA_CONFIG_PATH",config);
    let a=(0..257*2).map(|index|[1<<24,-(1<<23),-(1<<25),1<<24][index%4]).collect::<Vec<i32>>();
    let b=(0..263*2).map(|index|[-(1<<23),1<<22,0,0][index%4]).collect::<Vec<i32>>();let media=Arc::new(HashMap::from([("first".to_owned(),pcm_wav(&a)),("second".to_owned(),pcm_wav(&b))]));
    let mut kernel=vec![0.;65];kernel[0]=2.;kernel[64]=-3.;let first=impulse_samples(48000,&kernel);let other=impulse_samples(96000,&[5.]);let ids=vec![id(&other),id(&first)];
    let mut response=manifest(&first);response["items"].as_array_mut().unwrap().insert(0,manifest(&other)["items"][0].clone());let files=Arc::new(HashMap::from([(id(&first),first),(id(&other),other.clone())]));
    let posted=Arc::new(AtomicUsize::new(0));let posts=posted.clone();let downloads=Arc::new(AtomicUsize::new(0));let gets=downloads.clone();let manifest_response=response.clone();let files_read=files.clone();
    let handoffs=Arc::new(Mutex::new(Vec::<Value>::new()));let committed=handoffs.clone();let ends=Arc::new(Mutex::new(Vec::<Value>::new()));let ended=ends.clone();let finished=Arc::new(tokio::sync::Notify::new());let end_signal=finished.clone();
    let(profile,http_task)=server(Router::new().route("/api/v1/media/{source}",get(move|Path(source):Path<String>|{let media=media.clone();async move{media[&source].clone()}}))
        .route("/api/v1/zones/z/dsp/impulses",post(move|headers:HeaderMap,Json(body):Json<Value>|{let response=manifest_response.clone();let posts=posts.clone();async move{assert_eq!(headers["authorization"],"Bearer control-only");assert_eq!(body["response_ids"],json!(response["items"].as_array().unwrap().iter().map(|item|item["asset"]["id"].clone()).collect::<Vec<_>>()));posts.fetch_add(1,Ordering::Relaxed);Json(response)}}))
        .route("/api/v1/dsp/impulses/{id}/file",get(move|Path(id):Path<String>,Query(query):Query<HashMap<String,String>>,headers:HeaderMap|{let files=files_read.clone();let gets=gets.clone();async move{assert_eq!(headers["authorization"],"Bearer control-only");assert_eq!(query["ticket"],"selected-only");gets.fetch_add(1,Ordering::Relaxed);files[&id].clone()}}))
        .route("/api/v1/zones/z/prepare",post(|Json(body):Json<Value>|async move{Json(json!({"accepted":true,"plan_id":"plan","items":if body["playback_id"]=="core-first"{vec![json!({"playback_id":"core-second","track":{"id":"second"},"media_path":"api/v1/media/second"})]}else{vec![]},"has_more":false}))}))
        .route("/api/v1/zones/z/handoff",post(move|Json(body):Json<Value>|{let committed=committed.clone();async move{committed.lock().unwrap().push(body.clone());Json(json!({"accepted":true,"zone":{"playback_id":body["current"]["playback_id"],"status":"playing"}}))}}))
        .route("/api/v1/zones/z/ended",post(move|Json(body):Json<Value>|{let ended=ended.clone();let signal=end_signal.clone();async move{ended.lock().unwrap().push(body);signal.notify_one();Json(json!({"accepted":true}))}}))).await;
    let mut playback=Playback::connected(profile.clone(),"control-only".into(),"endpoint".into()).unwrap();let mut command=play(&profile,"first","first");command["muted"]=json!(false);command["volume"]=json!(1.);command["dsp"]=json!({"enabled":true,"convolution":{"response_ids":ids}});playback.command("play",&command,&profile).unwrap();ready(&mut playback).await;
    let bank=playback.pending.as_ref().unwrap().plan.impulse.as_ref().unwrap();assert_eq!(bank.response(48000).unwrap().kernels()[0],kernel);assert_eq!(bank.response(96000).unwrap().kernels()[0],[5.]);
    let (reports,mut received)=tokio::sync::mpsc::unbounded_channel();assert!(playback.start_ready(&OutputConfig{device_id:Some("capture".into()),..Default::default()},&reports).is_none());let control=playback.running.as_ref().unwrap().control.clone();assert!(playback.running.as_ref().unwrap().sequence.is_some());
    let mut paths=Vec::new();tokio::time::timeout(Duration::from_secs(10),async{loop{tokio::select!{_=finished.notified()=>break,report=received.recv()=>{let report=report.unwrap();assert_ne!(report["type"],"error","{report}");if report["signal_path"].is_object(){paths.push(report["signal_path"].clone());}}}}}).await.unwrap();
    let source=a.into_iter().chain(b).collect::<Vec<_>>();let mut expected=vec![0_i32;(520+64)*2];
    for (index,sample) in source.iter().enumerate(){expected[index]+=sample*2;expected[index+64*2]-=sample*3;}
    let expected=expected.iter().flat_map(|sample|sample.to_le_bytes()).collect::<Vec<_>>();assert_eq!(std::fs::read(&capture).unwrap(),expected);assert_eq!(control.frames_written.load(Ordering::Acquire),584);assert_eq!(control.frames_played.load(Ordering::Acquire),584);assert_eq!(control.seconds(48000),520./48000.);assert_eq!(posted.load(Ordering::Relaxed),1);assert_eq!(downloads.load(Ordering::Relaxed),2);
    while let Ok(report)=received.try_recv(){assert_ne!(report["type"],"error","{report}");if report["signal_path"].is_object(){paths.push(report["signal_path"].clone());}}
    let handoffs=handoffs.lock().unwrap().clone();assert_eq!(handoffs.len(),1);assert_eq!(handoffs[0]["ended"][0]["frames"],257);assert_eq!(handoffs[0]["ended"][0]["playback_id"],"core-first");assert_eq!(handoffs[0]["current"]["playback_id"],"core-second");assert_eq!(ends.lock().unwrap()[0]["frames"],263);assert!(paths.iter().any(|path|path["processing"].as_array().unwrap().iter().any(|stage|stage.as_str().is_some_and(|stage|stage.contains("FIR")&&stage.contains("48000 Hz")))));playback.shutdown().await;http_task.abort();

    // A loaded 96 kHz response must not substitute for the actual 48 kHz ALSA format.
    let response=manifest(&other);let bytes=other.clone();let(profile,server)=server(Router::new().route("/api/v1/media/source",get(||async{pcm_wav(&[1<<24,-(1<<23)])})).route("/api/v1/zones/z/dsp/impulses",post(move||{let response=response.clone();async move{Json(response)}})).route("/api/v1/dsp/impulses/{id}/file",get(move||{let bytes=bytes.clone();async move{bytes}}))).await;
    let mut playback=Playback::connected(profile.clone(),"control-only".into(),"endpoint".into()).unwrap();let mut command=play(&profile,"missing","source");command["dsp"]=serde_json::to_value(dsp(&other,true)).unwrap();playback.command("play",&command,&profile).unwrap();ready(&mut playback).await;let(reports,mut received)=tokio::sync::mpsc::unbounded_channel();assert!(playback.start_ready(&OutputConfig{device_id:Some("missing".into()),..Default::default()},&reports).is_none());
    let report=tokio::time::timeout(Duration::from_secs(5),received.recv()).await.unwrap().unwrap();assert_eq!(report["type"],"error");assert!(report["error"].as_str().unwrap().contains("缺少 48000 Hz"));assert_eq!(playback.running.as_ref().unwrap().control.frames_written.load(Ordering::Acquire),0);assert_eq!(playback.running.as_ref().unwrap().control.frames_played.load(Ordering::Acquire),0);
    match std::fs::read(&missing){Ok(bytes)=>assert!(bytes.is_empty()),Err(error)=>assert_eq!(error.kind(),std::io::ErrorKind::NotFound)}playback.shutdown().await;server.abort();
    if let Some(directory)=std::env::var_os("RMUSIC_FIR_QA_DIR") {
        let directory=std::path::PathBuf::from(directory);std::fs::create_dir_all(&directory).unwrap();std::fs::copy(&capture,directory.join("bridge-alsa-captured.pcm")).unwrap();std::fs::write(directory.join("bridge-alsa-expected.pcm"),&expected).unwrap();std::fs::write(directory.join("bridge-alsa-source.pcm"),source.iter().flat_map(|sample|sample.to_le_bytes()).collect::<Vec<_>>()).unwrap();
        std::fs::write(directory.join("bridge-alsa-result.json"),serde_json::to_vec_pretty(&json!({"passed":true,"programme_frames":520,"physical_frames":584,"tail_frames":64,"processing_rate":48000,"downloaded_response_rates":[96000,48000],"manifest_requests":posted.load(Ordering::Relaxed),"asset_downloads":downloads.load(Ordering::Relaxed),"kernel":kernel,"handoffs":handoffs,"ended":ends.lock().unwrap().clone(),"signal_paths":paths,"missing_rate_error":report,"missing_rate_output_frames":0,"reference":"Independent integer direct time-domain convolution; stereo S32LE bytes exact","scope":"Actual Playback command/preparation/continuous worker, HTTP fixture, FFmpeg and ALSA file/null; no production Core, DAC or listening journal"})).unwrap()).unwrap();
    }
}
